CREATE OR REPLACE FUNCTION public._registar_oferta_tvde()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_d        record;
  v_online   boolean;
  v_janela   integer;
  v_desfecho text;
  v_reforco  boolean;
BEGIN
  IF OLD.current_offer_driver_id IS NOT NULL
     AND (NEW.current_offer_driver_id IS DISTINCT FROM OLD.current_offer_driver_id
          OR NEW.status IS DISTINCT FROM OLD.status) THEN
    v_desfecho := CASE
      WHEN NEW.driver_id IS NOT NULL AND NEW.driver_id = OLD.current_offer_driver_id THEN 'aceite'
      WHEN NEW.status LIKE 'cancelada%' THEN 'pedido_cancelado'
      WHEN NEW.status = 'sem_motorista' THEN 'sem_motorista'
      WHEN OLD.offer_expires_at IS NOT NULL AND OLD.offer_expires_at > now() + interval '2 seconds' THEN 'recusou'
      ELSE 'expirou' END;
    UPDATE public.ofertas_prestador_log
       SET desfecho = v_desfecho, fechada_em = now()
     WHERE booking_id = NEW.id AND categoria = 'tvde' AND desfecho IS NULL;
  END IF;

  IF NEW.current_offer_driver_id IS NOT NULL
     AND NEW.current_offer_driver_id IS DISTINCT FROM OLD.current_offer_driver_id
     AND NEW.status = 'solicitada' THEN
    SELECT d.id, d.user_id AS uid, d.name, d.is_online, d.last_heartbeat_at, d.fcm_token
      INTO v_d FROM public.drivers d WHERE d.user_id = NEW.current_offer_driver_id LIMIT 1;
    v_online := COALESCE(v_d.is_online, false) AND v_d.last_heartbeat_at > now() - interval '90 seconds';
    v_janela := CASE WHEN NEW.offer_expires_at IS NULL THEN NULL
                     ELSE GREATEST(1, EXTRACT(EPOCH FROM (NEW.offer_expires_at - now()))::int) END;
    v_reforco := EXISTS (SELECT 1 FROM public.tvde_ride_events e
                          WHERE e.ride_id = NEW.id AND e.status = 'oferta'
                            AND e.meta->>'driver_id' = NEW.current_offer_driver_id::text
                            AND COALESCE((e.meta->>'forcado')::boolean, false)
                            AND e.at > now() - interval '30 seconds');
    INSERT INTO public.ofertas_prestador_log
      (categoria, booking_id, pedido_ref, prestador_id, user_id, nome, tem_aparelho,
       janela_min, janela_s, fase, estava_online)
    VALUES
      ('tvde', NEW.id, NEW.id::text, v_d.id, NEW.current_offer_driver_id, v_d.name,
       COALESCE(v_d.fcm_token, '') <> ''
         OR EXISTS (SELECT 1 FROM public.driver_push_tokens t WHERE t.user_id = NEW.current_offer_driver_id AND t.active),
       COALESCE(CEIL(v_janela / 60.0)::int, 0), v_janela,
       CASE WHEN v_reforco THEN 'forcado' WHEN v_online THEN 'online' ELSE 'desligado' END,
       v_online);
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    INSERT INTO public.notification_failures (kind, source, erro)
    VALUES ('registo_oferta', '_registar_oferta_tvde', left(NEW.id::text || ': ' || SQLERRM, 500));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[_registar_oferta_tvde] % (registo da falha também falhou: %)', NEW.id, SQLERRM;
  END;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public._tvde_chamada_de_reforco()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_t      integer;
  v_feitos uuid[];
  v_prox   uuid;
  v_ttl    integer;
BEGIN
  IF NOT (OLD.status = 'solicitada' AND NEW.status = 'sem_motorista') THEN RETURN NEW; END IF;
  -- Reservas (têm devolução própria), balcão e corridas retidas: como hoje.
  IF NEW.reservation_status IS NOT NULL OR OLD.reservation_status IS NOT NULL
     OR COALESCE(NEW.source, 'app') = 'balcao' OR NEW.dispatch_hold_reason IS NOT NULL THEN
    RETURN NEW;
  END IF;
  BEGIN
    IF NOT COALESCE((public.get_setting('tvde_forcado_ligado') #>> '{}')::boolean, false) THEN RETURN NEW; END IF;
    v_t := COALESCE((public.get_setting('tvde_forcado_tentativas') #>> '{}')::int, 2);
    SELECT COALESCE(array_agg(DISTINCT l.user_id) FILTER (WHERE l.user_id IS NOT NULL), '{}'::uuid[]) INTO v_feitos
      FROM public.ofertas_prestador_log l
     WHERE l.categoria = 'tvde' AND l.booking_id = NEW.id AND l.fase = 'forcado';
    IF cardinality(v_feitos) >= v_t THEN RETURN NEW; END IF;
    SELECT f.user_id INTO v_prox FROM public._tvde_forcados(NEW.id) f
     WHERE NOT (f.user_id = ANY(v_feitos)) ORDER BY f.ordem, f.visto_em DESC LIMIT 1;
    IF v_prox IS NULL THEN RETURN NEW; END IF;
    v_ttl := COALESCE((public.get_setting('tvde_offer_ttl_seconds') #>> '{}')::int, 40);
    INSERT INTO public.tvde_ride_events (ride_id, status, actor, meta)
      VALUES (NEW.id, 'oferta', 'system',
              jsonb_build_object('driver_id', v_prox, 'expires_in_s', v_ttl, 'forcado', true,
                                 'motivo', 'chamada_de_reforco'));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[_tvde_chamada_de_reforco] %: %', NEW.id, SQLERRM;
    RETURN NEW;
  END;
  -- Em vez de fechar "sem motorista", fica a procurar com a oferta de reforço.
  NEW.status := 'solicitada';
  NEW.cancel_reason := OLD.cancel_reason;
  NEW.current_offer_driver_id := v_prox;
  NEW.offer_expires_at := now() + make_interval(secs => v_ttl);
  NEW.no_driver_since := NULL;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_notify_tvde_client_on_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net', 'extensions'
AS $function$
DECLARE v_jwt text; v_body jsonb; v_nome text; v_titulo text; v_corpo text;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN RETURN NEW; END IF;
  IF NEW.status NOT IN (
       'motorista_atribuido','motorista_a_caminho','motorista_chegou',
       'em_andamento','finalizada','sem_motorista','cancelada_motorista'
     ) THEN
    RETURN NEW;
  END IF;

  v_body := jsonb_build_object('rideId', NEW.id::text, 'status', NEW.status);

  -- 21/10/2026 (fechar-pendencias A1): numa ENCOMENDA o texto fala da encomenda.
  IF NEW.ride_kind = 'encomendas' THEN
    IF NEW.driver_id IS NOT NULL THEN
      SELECT nullif(trim(d.name), '') INTO v_nome
        FROM public.drivers d WHERE d.user_id = NEW.driver_id;
    END IF;
    v_nome := coalesce(v_nome, 'O teu estafeta');
    CASE NEW.status
      WHEN 'motorista_atribuido', 'motorista_a_caminho' THEN
        v_titulo := '📦 Estafeta a caminho da recolha';
        v_corpo  := v_nome || ' vem buscar a tua encomenda.';
      WHEN 'motorista_chegou' THEN
        v_titulo := '📍 O estafeta chegou à recolha';
        v_corpo  := v_nome || ' está no local de recolha.';
      WHEN 'em_andamento' THEN
        v_titulo := '📦 Encomenda recolhida';
        v_corpo  := 'A tua encomenda vai a caminho da entrega. O preço é o que viste ao pedir.';
      WHEN 'finalizada' THEN
        v_titulo := '✅ Encomenda entregue';
        v_corpo  := 'A entrega foi concluída. Avalia a entrega na app.';
      WHEN 'sem_motorista' THEN
        v_titulo := '😕 Sem estafetas disponíveis';
        v_corpo  := 'Não encontrámos estafeta a tempo e o pedido foi cancelado. Se pagaste na app, o valor é devolvido. Podes tentar de novo.';
      WHEN 'cancelada_motorista' THEN
        v_titulo := 'Entrega cancelada';
        v_corpo  := 'O estafeta cancelou a entrega. Pedimos desculpa — tenta de novo.';
      ELSE
        v_titulo := NULL;
    END CASE;
    IF v_titulo IS NOT NULL THEN
      v_body := v_body || jsonb_build_object('titulo', v_titulo, 'corpo', v_corpo);
    END IF;
  END IF;

  v_jwt := public._dispatch_jwt();
  PERFORM net.http_post(
    url     := 'https://ojykpzwqrtusfeakzrna.supabase.co/functions/v1/notify-tvde-client',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_jwt),
    body    := v_body
  );
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.fn_notify_tvde_driver_on_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net', 'extensions'
AS $function$
DECLARE v_jwt text;
BEGIN
  IF NEW.current_offer_driver_id IS NULL THEN RETURN NEW; END IF;
  IF OLD.current_offer_driver_id IS NOT DISTINCT FROM NEW.current_offer_driver_id THEN RETURN NEW; END IF;
  v_jwt := public._dispatch_jwt();
  PERFORM net.http_post(
    url     := 'https://ojykpzwqrtusfeakzrna.supabase.co/functions/v1/notify-tvde-driver',
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_jwt),
    body    := jsonb_build_object('driverId', NEW.current_offer_driver_id::text, 'rideId', NEW.id::text)
  );
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.get_setting(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row    record;
  v_claims text;
  v_role   text;
  v_admin  boolean := false;
begin
  select value, is_secret into v_row from public.platform_settings where key = p_key;
  if not found then return null; end if;
  if not v_row.is_secret then return v_row.value; end if;

  -- Chave sensível: só passa a quem tem autoridade.
  v_claims := nullif(current_setting('request.jwt.claims', true), '');
  if v_claims is not null then
    begin
      v_role := v_claims::jsonb ->> 'role';
    exception when others then
      v_role := null;
    end;
    if v_role = 'service_role' then
      return v_row.value;
    end if;
    begin
      v_admin := public.is_admin();
    exception when others then
      v_admin := false;
    end;
    if v_admin then return v_row.value; end if;
    return null;
  end if;

  -- Sem claims: só o próprio servidor (o current_user aqui dentro é sempre o dono da função).
  if session_user in ('postgres', 'supabase_admin') then
    return v_row.value;
  end if;
  return null;
end $function$

CREATE OR REPLACE FUNCTION public.tvde_driver_offer_allowed(p_driver uuid, p_ride uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.tvde_rides; d public.drivers; v_lim numeric;
begin
  -- 2026-10-14: quem desligou o TVDE na app nao recebe ofertas de corrida (o push nem lhe chega)
  if not public.aceita_papel(p_driver, 'driver') then
    return false;
  end if;
  if not coalesce((public.get_setting('tvde_compliance_enforce') #>> '{}')::boolean, false) then
    return true;
  end if;
  if public.tvde_conf_ativa('tvde_compliance_block')
     and jsonb_array_length(public._tvde_conformidade_calc(p_driver)->'motivos') > 0 then
    return false;
  end if;
  if public.tvde_conf_ativa('tvde_work_limit_enforce') then
    v_lim := coalesce((public.get_setting('tvde_work_limit_hours') #>> '{}')::numeric, 10);
    if public.tvde_driver_horas_total(p_driver) >= v_lim then return false; end if;
  end if;
  if p_ride is not null and public.tvde_conf_ativa('tvde_pref_matching_enforce') then
    select * into r from public.tvde_rides where id = p_ride;
    select * into d from public.drivers where user_id = p_driver limit 1;
    if r.pref_fala_portugues and d.fala_portugues is not true then return false; end if;
    if r.pede_mobilidade_reduzida and not exists (
         select 1 from public.tvde_driver_vehicle dv join public.tvde_vehicles v on v.id = dv.vehicle_id
          where dv.driver_user_id = p_driver and dv.ativo and v.adaptado_mobilidade_reduzida) then
      return false;
    end if;
  end if;
  return true;
exception when others then
  begin
    insert into public.e2e_log (fluxo, passo, estado, detalhe, device)
    values ('tvde-conformidade', 'offer_allowed', 'falhou', p_driver || ' ' || sqlerrm, 'db');
  exception when others then null;
  end;
  return true;
end $function$
